import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.DNmTgtHf.js";const k=JSON.parse('{"title":"Thread Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"java/concurrency/thread_lifecycle/ThreadLifecycle.md","filePath":"java/concurrency/thread_lifecycle/ThreadLifecycle.md"}'),n={name:"java/concurrency/thread_lifecycle/ThreadLifecycle.md"};function o(d,e,r,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="thread-lifecycle" tabindex="-1">Thread Lifecycle <a class="header-anchor" href="#thread-lifecycle" aria-label="Permalink to &quot;Thread Lifecycle&quot;">​</a></h1><hr><h2 id="the-6-states" tabindex="-1">The 6 states <a class="header-anchor" href="#the-6-states" aria-label="Permalink to &quot;The 6 states&quot;">​</a></h2><p>Defined in <code>Thread.State</code>. The JVM tracks each thread&#39;s state; <code>Thread.getState()</code> returns the current value.</p><table tabindex="0"><thead><tr><th>State</th><th>What it means at JVM level</th></tr></thead><tbody><tr><td>NEW</td><td>Thread object created, <code>start()</code> not yet called. No OS thread exists yet.</td></tr><tr><td>RUNNABLE</td><td>OS thread exists and is either running on a CPU core or waiting in the OS scheduler&#39;s run queue. Java doesn&#39;t distinguish the two.</td></tr><tr><td>BLOCKED</td><td>Waiting to acquire an intrinsic monitor lock (<code>synchronized</code> block/method). Another thread holds the lock.</td></tr><tr><td>WAITING</td><td>Indefinitely suspended — voluntarily gave up the CPU. Woken only when another thread explicitly notifies or unparks it.</td></tr><tr><td>TIMED_WAITING</td><td>Same as WAITING but with a deadline. JVM resumes the thread after the timeout even if no notification arrives.</td></tr><tr><td>TERMINATED</td><td><code>run()</code> returned or threw an uncaught exception. Thread is dead — cannot be restarted.</td></tr></tbody></table><hr><h2 id="state-diagram" tabindex="-1">State diagram <a class="header-anchor" href="#state-diagram" aria-label="Permalink to &quot;State diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [*] --&gt; NEW : new Thread()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NEW --&gt; RUNNABLE : start()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RUNNABLE --&gt; BLOCKED : entering synchronized (lock held by another)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BLOCKED --&gt; RUNNABLE : lock acquired</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RUNNABLE --&gt; WAITING : wait() / join() / park()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WAITING --&gt; RUNNABLE : notify() / notifyAll() / unpark() / join target terminates</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RUNNABLE --&gt; TIMED_WAITING : sleep(ms) / wait(ms) / join(ms) / parkNanos()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TIMED_WAITING --&gt; RUNNABLE : timeout expires OR notify() / unpark()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RUNNABLE --&gt; TERMINATED : run() completes or throws</span></span></code></pre></div><hr><h2 id="key-transitions" tabindex="-1">Key transitions <a class="header-anchor" href="#key-transitions" aria-label="Permalink to &quot;Key transitions&quot;">​</a></h2><h3 id="start" tabindex="-1"><code>start()</code> <a class="header-anchor" href="#start" aria-label="Permalink to &quot;`start()`&quot;">​</a></h3><p>Allocates an OS thread, moves the thread from NEW → RUNNABLE. Calling <code>start()</code> twice throws <code>IllegalThreadStateException</code>.</p><h3 id="entering-exiting-a-synchronized-block" tabindex="-1">Entering / exiting a <code>synchronized</code> block <a class="header-anchor" href="#entering-exiting-a-synchronized-block" aria-label="Permalink to &quot;Entering / exiting a `synchronized` block&quot;">​</a></h3><ul><li>A thread trying to enter a <code>synchronized</code> block moves RUNNABLE → BLOCKED if the intrinsic lock is held by another thread.</li><li>When the lock is released, one of the contending BLOCKED threads is promoted back to RUNNABLE (which one is unspecified — OS scheduler decides).</li></ul><h3 id="object-wait-notify-notifyall" tabindex="-1"><code>Object.wait()</code> / <code>notify()</code> / <code>notifyAll()</code> <a class="header-anchor" href="#object-wait-notify-notifyall" aria-label="Permalink to &quot;`Object.wait()` / `notify()` / `notifyAll()`&quot;">​</a></h3><ul><li><code>wait()</code> — must hold the monitor lock. Atomically releases the lock and moves the calling thread RUNNABLE → WAITING (or TIMED_WAITING if called with a timeout). On wake, must re-acquire the lock before continuing.</li><li><code>notify()</code> — wakes one arbitrary WAITING thread on that object&#39;s monitor. The woken thread moves WAITING → BLOCKED (must re-acquire the lock).</li><li><code>notifyAll()</code> — wakes all WAITING threads. Each moves WAITING → BLOCKED and races for the lock.</li><li>Common pitfall: <code>wait()</code> can wake spuriously (with no notification). Always call it inside a <code>while</code> loop checking the condition, not an <code>if</code>.</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronized</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (lock) {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">conditionMet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) {   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// NOT if — guards against spurious wakeups</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // proceed</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="thread-sleep-ms" tabindex="-1"><code>Thread.sleep(ms)</code> <a class="header-anchor" href="#thread-sleep-ms" aria-label="Permalink to &quot;`Thread.sleep(ms)`&quot;">​</a></h3><p>Moves RUNNABLE → TIMED_WAITING. Does <strong>not</strong> release any held monitor locks. Resumes after the timeout or on interrupt.</p><h3 id="thread-join-thread-join-ms" tabindex="-1"><code>thread.join()</code> / <code>thread.join(ms)</code> <a class="header-anchor" href="#thread-join-thread-join-ms" aria-label="Permalink to &quot;`thread.join()` / `thread.join(ms)`&quot;">​</a></h3><p>Calling thread moves RUNNABLE → WAITING (or TIMED_WAITING). Resumes when the target thread reaches TERMINATED, or when the timeout expires.</p><h3 id="locksupport-park-unpark-thread" tabindex="-1"><code>LockSupport.park()</code> / <code>unpark(thread)</code> <a class="header-anchor" href="#locksupport-park-unpark-thread" aria-label="Permalink to &quot;`LockSupport.park()` / `unpark(thread)`&quot;">​</a></h3><p>Low-level primitives underlying <code>java.util.concurrent</code> locks.</p><ul><li><code>park()</code> moves RUNNABLE → WAITING. <code>parkNanos()</code>/<code>parkUntil()</code> → TIMED_WAITING.</li><li><code>unpark(t)</code> wakes thread <code>t</code>. If <code>unpark</code> is called before <code>park</code>, the next <code>park</code> call returns immediately (one permit is &quot;pre-loaded&quot;).</li><li>Unlike <code>wait()</code>, <code>park()</code> does <strong>not</strong> require holding a lock.</li></ul><hr><h2 id="blocked-vs-waiting-—-the-key-distinction" tabindex="-1">BLOCKED vs WAITING — the key distinction <a class="header-anchor" href="#blocked-vs-waiting-—-the-key-distinction" aria-label="Permalink to &quot;BLOCKED vs WAITING — the key distinction&quot;">​</a></h2><p>Interviewers use this question to filter shallow from deep knowledge.</p><table tabindex="0"><thead><tr><th></th><th>BLOCKED</th><th>WAITING</th></tr></thead><tbody><tr><td>Cause</td><td>Trying to enter a <code>synchronized</code> block/method and the lock is taken</td><td>Voluntarily suspended via <code>wait()</code>, <code>join()</code>, or <code>park()</code></td></tr><tr><td>Who decides when it ends</td><td>OS/JVM when the lock is released by another thread</td><td>Another thread explicitly calling <code>notify()</code>, <code>notifyAll()</code>, or <code>unpark()</code></td></tr><tr><td>Lock held while suspended</td><td>No</td><td>No (for <code>wait()</code>, the lock is released atomically on entry)</td></tr><tr><td>Timeout variant</td><td>None — BLOCKED has no timeout</td><td>Yes → TIMED_WAITING</td></tr></tbody></table><p>One sentence for the interview: <strong>BLOCKED is involuntary contention on a monitor lock; WAITING is a voluntary, indefinite suspension waiting for a signal.</strong></p><hr><h2 id="timed-waiting" tabindex="-1">TIMED_WAITING <a class="header-anchor" href="#timed-waiting" aria-label="Permalink to &quot;TIMED_WAITING&quot;">​</a></h2><p>Same semantics as WAITING — thread is suspended and not consuming CPU — but resumes after a wall-clock deadline even without a signal. Methods that produce TIMED_WAITING:</p><ul><li><code>Thread.sleep(long millis)</code></li><li><code>Object.wait(long timeout)</code></li><li><code>Thread.join(long millis)</code></li><li><code>LockSupport.parkNanos(long nanos)</code> / <code>LockSupport.parkUntil(long deadline)</code></li><li><code>Condition.await(long time, TimeUnit unit)</code></li></ul><hr><h2 id="daemon-threads" tabindex="-1">Daemon threads <a class="header-anchor" href="#daemon-threads" aria-label="Permalink to &quot;Daemon threads&quot;">​</a></h2><p>A daemon thread is a background thread whose lifecycle is tied to the JVM process, not to other threads.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Thread t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Thread</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(task);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDaemon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// must be called before start()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p><strong>Rule:</strong> when all non-daemon (user) threads have finished, the JVM exits even if daemon threads are still running. Daemon threads are abruptly killed — no <code>finally</code> blocks, no shutdown hooks run on their behalf.</p><p>Use cases: GC threads, JIT compiler threads, background housekeeping (e.g., a cache eviction loop). Do not use daemon threads for tasks that must complete (e.g., writing to a database).</p><hr><h2 id="interrupt-mechanics" tabindex="-1"><code>interrupt()</code> mechanics <a class="header-anchor" href="#interrupt-mechanics" aria-label="Permalink to &quot;`interrupt()` mechanics&quot;">​</a></h2><p><code>interrupt()</code> sets the interrupted flag on the target thread. It does not stop the thread — it signals it.</p><p><strong>Two query methods:</strong></p><table tabindex="0"><thead><tr><th>Method</th><th>Type</th><th>Clears the flag?</th><th>Use when</th></tr></thead><tbody><tr><td><code>Thread.interrupted()</code></td><td>static, tests current thread</td><td>Yes</td><td>You&#39;re inside the thread and want to consume the signal</td></tr><tr><td><code>thread.isInterrupted()</code></td><td>instance</td><td>No</td><td>You&#39;re outside and only want to check</td></tr></tbody></table><p><strong>Blocking methods that respond to interruption</strong> (by throwing <code>InterruptedException</code>): <code>Object.wait()</code>, <code>Thread.sleep()</code>, <code>Thread.join()</code>, <code>BlockingQueue.take()</code>, <code>Lock.lockInterruptibly()</code>, <code>LockSupport.park()</code> (returns without throwing; caller must check <code>Thread.interrupted()</code>).</p><p>When a blocking method throws <code>InterruptedException</code>, it <strong>clears the interrupted flag</strong> as a side effect. If you catch it and don&#39;t re-interrupt, the flag is lost.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Thread.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sleep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">catch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (InterruptedException </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Thread.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">currentThread</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">interrupt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// restore the flag</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // then handle or propagate</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. What is the difference between BLOCKED and WAITING?</strong> A. BLOCKED = waiting to acquire a monitor lock held by another thread. WAITING = voluntarily suspended via <code>wait()</code>/<code>join()</code>/<code>park()</code>, waiting for an explicit signal.</p><p><strong>Q. Does <code>Thread.sleep()</code> release held monitor locks?</strong> A. No. The thread sleeps but keeps all locks it holds.</p><p><strong>Q. What happens when the last non-daemon thread exits?</strong> A. The JVM exits immediately; all daemon threads are killed without running <code>finally</code> blocks.</p><p><strong>Q. What does <code>interrupt()</code> actually do?</strong> A. Sets the interrupted flag. If the thread is blocked in a method like <code>sleep()</code> or <code>wait()</code>, that method throws <code>InterruptedException</code> and clears the flag.</p><p><strong>Q. Why use <code>while</code> instead of <code>if</code> around <code>wait()</code>?</strong> A. <code>wait()</code> can wake spuriously (no notification). The <code>while</code> re-checks the condition and parks again if it isn&#39;t met.</p><p><strong>Q. What does <code>unpark</code> before <code>park</code> do?</strong> A. The permit is pre-loaded; the subsequent <code>park()</code> call returns immediately without blocking.</p><p><strong>Q. Can you call <code>start()</code> on a terminated thread?</strong> A. No — throws <code>IllegalThreadStateException</code>. A thread can only be started once.</p>',56)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
